diff --git a/tests/e2e/flows/messages/notifications.ts b/tests/e2e/flows/messages/notifications.ts
new file mode 100644
index 0000000..abe869b
--- /dev/null
+++ b/tests/e2e/flows/messages/notifications.ts
@@ -0,0 +1,265 @@
+import type { BrowserContext, Page } from '@playwright/test';
+import { expect } from '../_support/index.js';
+import { openSettings } from '../settings/settings-page.js';
+
+// Browser notifications (Messages spec, section 3, Unread and notifications). Test browsers show no
+// real notifications and can't reach a push service, so a stand-in for the browser's Notification
+// API notes what Care Hub shows, can click a notification, and can put the tab in the background.
+// It assumes that a Care Hub tab that is open in the background shows notifications itself (with
+// `new Notification` or the service worker registration's `showNotification`); web push is for
+// when Care Hub isn't open.
+
+/** A notification Care Hub showed. `fromWorker` when it came through the service worker. */
+export type Shown = {
+  title: string;
+  body: string;
+  tag: string;
+  data: unknown;
+  fromWorker: boolean;
+};
+
+type StandIn = {
+  permission(): string;
+  shown(): Shown[];
+  click(index: number): void;
+  background(on: boolean): void;
+};
+type WithStandIn = { qaNotifications: StandIn };
+
+/** Runs in each page before Care Hub's code. The permission is kept across reloads of the tab. */
+function standIn(initial: NotificationPermission): void {
+  const key = 'qa:notification-permission';
+  let permission = initial;
+  try {
+    permission = (sessionStorage.getItem(key) as NotificationPermission | null) ?? initial;
+  } catch {
+    // about:blank has no storage.
+  }
+  let background = false;
+  const shown: Shown[] = [];
+  const targets: (StandInNotification | null)[] = [];
+  const plain = (value: unknown): unknown => {
+    try {
+      return JSON.parse(JSON.stringify(value ?? null));
+    } catch {
+      return null;
+    }
+  };
+
+  class StandInNotification extends EventTarget {
+    static get permission(): NotificationPermission {
+      return permission;
+    }
+    static async requestPermission(
+      callback?: (answer: NotificationPermission) => void,
+    ): Promise<NotificationPermission> {
+      permission = 'granted';
+      try {
+        sessionStorage.setItem(key, permission);
+      } catch {
+        // about:blank has no storage.
+      }
+      callback?.(permission);
+      return permission;
+    }
+    static readonly maxActions = 2;
+    readonly title: string;
+    readonly body: string;
+    readonly tag: string;
+    readonly data: unknown;
+    onclick: ((event: Event) => void) | null = null;
+    onshow: ((event: Event) => void) | null = null;
+    onclose: ((event: Event) => void) | null = null;
+    onerror: ((event: Event) => void) | null = null;
+    constructor(title: string, options: NotificationOptions = {}) {
+      super();
+      this.title = String(title);
+      this.body = options.body ?? '';
+      this.tag = options.tag ?? '';
+      this.data = options.data ?? null;
+      shown.push({
+        title: this.title,
+        body: this.body,
+        tag: this.tag,
+        data: plain(this.data),
+        fromWorker: false,
+      });
+      targets.push(this);
+      setTimeout(() => this.fire('show'), 0);
+    }
+    fire(type: 'show' | 'click' | 'close'): void {
+      const event = new Event(type, { cancelable: true });
+      this.dispatchEvent(event);
+      ({ show: this.onshow, click: this.onclick, close: this.onclose })[type]?.call(this, event);
+    }
+    close(): void {
+      this.fire('close');
+    }
+  }
+  Object.defineProperty(window, 'Notification', {
+    value: StandInNotification,
+    writable: true,
+    configurable: true,
+  });
+
+  if ('ServiceWorkerRegistration' in window) {
+    ServiceWorkerRegistration.prototype.showNotification = async function (
+      title: string,
+      options: NotificationOptions = {},
+    ) {
+      shown.push({
+        title: String(title),
+        body: options.body ?? '',
+        tag: options.tag ?? '',
+        data: plain(options.data),
+        fromWorker: true,
+      });
+      targets.push(null);
+    };
+    ServiceWorkerRegistration.prototype.getNotifications = async () => [];
+  }
+  // No push service here: subscribing fails at once, as in a browser without one.
+  if ('PushManager' in window) {
+    PushManager.prototype.subscribe = async () => {
+      throw new DOMException('No push service in this test browser.', 'NotSupportedError');
+    };
+    PushManager.prototype.getSubscription = async () => null;
+  }
+  const query = navigator.permissions?.query.bind(navigator.permissions);
+  if (query) {
+    navigator.permissions.query = (descriptor: PermissionDescriptor) =>
+      descriptor.name === 'notifications'
+        ? Promise.resolve(
+            Object.assign(new EventTarget(), {
+              name: 'notifications',
+              state: permission === 'default' ? 'prompt' : permission,
+              onchange: null,
+            }) as unknown as PermissionStatus,
+          )
+        : query(descriptor);
+  }
+
+  // The tab in the background: hidden and without focus.
+  const visibility = Object.getOwnPropertyDescriptor(Document.prototype, 'visibilityState');
+  const hidden = Object.getOwnPropertyDescriptor(Document.prototype, 'hidden');
+  Object.defineProperty(Document.prototype, 'visibilityState', {
+    configurable: true,
+    get(this: Document) {
+      return background ? 'hidden' : visibility?.get?.call(this);
+    },
+  });
+  Object.defineProperty(Document.prototype, 'hidden', {
+    configurable: true,
+    get(this: Document) {
+      return background || hidden?.get?.call(this);
+    },
+  });
+  const hasFocus = Document.prototype.hasFocus;
+  Document.prototype.hasFocus = function (this: Document) {
+    return !background && hasFocus.call(this);
+  };
+
+  const api: StandIn = {
+    permission: () => permission,
+    shown: () => shown.map((entry) => ({ ...entry })),
+    click: (index) => targets[index]?.fire('click'),
+    background: (on) => {
+      background = on;
+      document.dispatchEvent(new Event('visibilitychange'));
+      window.dispatchEvent(new Event(on ? 'blur' : 'focus'));
+    },
+  };
+  Object.defineProperty(window, 'qaNotifications', { value: api });
+}
+
+/** Puts the stand-in in every page of `context`. `permission` is what the browser answers so far. */
+export async function fakeNotifications(
+  context: BrowserContext,
+  permission: NotificationPermission = 'default',
+): Promise<void> {
+  await context.addInitScript(standIn, permission);
+}
+
+/** What the stand-in answers for the permission now: default, granted or denied. */
+export function notificationPermission(page: Page): Promise<string> {
+  return page.evaluate(() => (window as unknown as WithStandIn).qaNotifications.permission());
+}
+
+/** Puts the tab in the background (hidden, without focus) or back in front. */
+export async function toBackground(page: Page, on: boolean): Promise<void> {
+  await page.evaluate(
+    (value) => (window as unknown as WithStandIn).qaNotifications.background(value),
+    on,
+  );
+}
+
+/** The notifications shown since the page was loaded. */
+export function shownNotifications(page: Page): Promise<Shown[]> {
+  return page.evaluate(() => (window as unknown as WithStandIn).qaNotifications.shown());
+}
+
+/** Its title and text together, for checks on what it shows. */
+export const wording = (shown: Shown) => `${shown.title} · ${shown.body}`;
+
+/** Waits for a notification that `matches`; returns it and its place in the list. */
+export async function notificationWhere(
+  page: Page,
+  matches: (shown: Shown) => boolean,
+  what: string,
+): Promise<{ shown: Shown; index: number }> {
+  let list: Shown[] = [];
+  await expect
+    .poll(
+      async () => {
+        list = await shownNotifications(page);
+        return list.some(matches);
+      },
+      { message: what, timeout: 10_000 },
+    )
+    .toBe(true);
+  const index = list.findIndex(matches);
+  const shown = list[index];
+  if (!shown) throw new Error(`Not found: ${what}`);
+  return { shown, index };
+}
+
+/**
+ * Clicks a notification and brings the tab to the front. One the page showed gets its click; one
+ * shown through the service worker can't be clicked here, so the tab opens the Care Hub address in
+ * its data instead, which is what the worker opens on a click.
+ */
+export async function openNotification(
+  page: Page,
+  { shown, index }: { shown: Shown; index: number },
+): Promise<void> {
+  if (shown.fromWorker) {
+    const address = /"((?:https?:\/\/[^"]+)?\/messages[^"]*)"/.exec(
+      JSON.stringify(shown.data),
+    )?.[1];
+    expect(address, 'the address of the chat, in the notification').toBeTruthy();
+    await page.goto(address ?? '');
+  } else {
+    await page.evaluate(
+      (place) => (window as unknown as WithStandIn).qaNotifications.click(place),
+      index,
+    );
+    await toBackground(page, false);
+  }
+}
+
+/** Settings → Notifications: turns "Show message text in notifications" on or off. */
+export async function showMessageText(page: Page, on: boolean): Promise<void> {
+  await openSettings(page, 'Notifications');
+  const named = { name: /^show message text/i };
+  const toggle = page.getByRole('switch', named).or(page.getByRole('checkbox', named)).first();
+  if ((await toggle.isChecked()) !== on) {
+    const saved = page.waitForResponse(
+      (response) =>
+        new URL(response.url()).pathname.startsWith('/api/') &&
+        response.request().method() !== 'GET',
+    );
+    await toggle.click();
+    expect((await saved).ok(), 'saving "Show message text"').toBe(true);
+  }
+  await expect(toggle).toBeChecked({ checked: on });
+}

diff --git a/tests/e2e/flows/messages/message-actions.ts b/tests/e2e/flows/messages/message-actions.ts
new file mode 100644
index 0000000..8afae19
--- /dev/null
+++ b/tests/e2e/flows/messages/message-actions.ts
@@ -0,0 +1,282 @@
+import type { Locator, Page, Request } from '@playwright/test';
+import { apiFor, expect, type PersonKey } from '../_support/index.js';
+import { clickAndConfirm, swapped } from '../settings/account-page.js';
+import type { ApiAnswer } from '../status/status-page.js';
+import { firstName, messageRow, word } from './messages-page.js';
+
+// A message's menu, editing and deleting, reactions and message search (Messages spec, sections 2,
+// 3, 5 and 6). The flows note the requests the screens send, so they can send the same request as
+// someone else and check that the server refuses it.
+
+/** "This message was deleted", which stays where a deleted message was (section 3). */
+export const deletedLine = 'This message was deleted';
+
+/** A request that changed something on the server, as the browser sent it, and its answer. */
+export type Sent = {
+  method: 'POST' | 'PUT' | 'PATCH' | 'DELETE';
+  path: string;
+  data: unknown;
+  status: number;
+};
+
+function bodyOf(request: Request): unknown {
+  const text = request.postData();
+  if (!text) return undefined;
+  try {
+    return JSON.parse(text);
+  } catch {
+    return text;
+  }
+}
+
+/**
+ * Runs `action` and returns the first request to /api it made that changes something (not a GET)
+ * and that `matches`, once it's answered. `matches` keeps out requests the page sends by itself,
+ * such as marking a chat read.
+ */
+export async function capture(
+  page: Page,
+  matches: (request: Request) => boolean,
+  action: () => Promise<unknown>,
+): Promise<Sent> {
+  const sent = page.waitForRequest(
+    (request) =>
+      new URL(request.url()).pathname.startsWith('/api/') &&
+      request.method() !== 'GET' &&
+      matches(request),
+    { timeout: 10_000 },
+  );
+  // If the action fails first, its error is the one to report.
+  sent.catch(() => undefined);
+  await action();
+  const request = await sent;
+  const response = await request.response();
+  const { pathname, search } = new URL(request.url());
+  return {
+    method: request.method() as Sent['method'],
+    path: pathname + search,
+    data: bodyOf(request),
+    status: response?.status() ?? 0,
+  };
+}
+
+/**
+ * Sends a noted request again as the person signed in on `page`, about another message: every `from`
+ * ID in its address and body becomes `to`. Returns the status code.
+ */
+export async function sendAgain(page: Page, sent: Sent, from: string, to: string): Promise<number> {
+  const api = await apiFor(page);
+  const answer = await api.send(
+    sent.method,
+    sent.path.replaceAll(from, to),
+    swapped(sent.data, from, to),
+  );
+  return answer.status();
+}
+
+/**
+ * The IDs of the things in `answers` that have `text` as one of their values: the messages with that
+ * text, as the server sent them. Two IDs for one text means it was saved twice.
+ */
+export function idsWithText(answers: ApiAnswer[], text: string): string[] {
+  const ids = new Set<string>();
+  const visit = (value: unknown): void => {
+    if (Array.isArray(value)) {
+      value.forEach(visit);
+    } else if (value && typeof value === 'object') {
+      const { id } = value as { id?: unknown };
+      const values = Object.values(value);
+      if ((typeof id === 'string' || typeof id === 'number') && values.includes(text)) {
+        ids.add(String(id));
+      }
+      values.forEach(visit);
+    }
+  };
+  answers.forEach((answer) => visit(answer.body));
+  return [...ids];
+}
+
+/** The IDs for `text` in the answers, once the server has sent it at least once. */
+export async function sentIds(answers: ApiAnswer[], text: string): Promise<string[]> {
+  await expect
+    .poll(() => idsWithText(answers, text).length, { message: `the server sends "${text}"` })
+    .toBeGreaterThan(0);
+  return idsWithText(answers, text);
+}
+
+// ---- A message's menu (section 6: Edit, Delete, Copy text, Add reaction, Download files) ----
+
+/** The button that opens a message's menu, shown when pointing at the message. */
+const menuButtonName =
+  /^(more|more actions|more options|actions|options|message (actions|menu|options))$/i;
+
+/**
+ * Opens a message's menu: with its button when pointing at the message, or with Enter on the
+ * message (section 6). Every message's menu has Copy text.
+ */
+export async function openMessageMenu(page: Page, text: string): Promise<Locator> {
+  const row = messageRow(page, text);
+  await row.hover();
+  const button = row.getByRole('button', { name: menuButtonName }).first();
+  const pointed = await button.waitFor({ timeout: 2_000 }).then(
+    () => true,
+    () => false,
+  );
+  if (pointed) {
+    await button.click();
+  } else {
+    await row.focus();
+    await row.press('Enter');
+  }
+  const menu = page
+    .getByRole('menu')
+    .filter({ has: page.getByRole('menuitem', { name: 'Copy text' }) })
+    .last();
+  await expect(menu).toBeVisible();
+  return menu;
+}
+
+/** Edit in the message's menu: replaces its text and saves with Enter. Returns the request sent. */
+export async function editMessage(page: Page, text: string, newText: string): Promise<Sent> {
+  const menu = await openMessageMenu(page, text);
+  await menu.getByRole('menuitem', { name: 'Edit', exact: true }).click();
+  // The edit box takes the focus, in the message or in the composer.
+  const box = page.locator(':focus');
+  await expect(box).toBeEditable();
+  await box.fill(newText);
+  return capture(
+    page,
+    (request) => (request.postData() ?? '').includes(newText),
+    () => box.press('Enter'),
+  );
+}
+
+/** Delete in the message's menu, and its confirmation. Returns the request sent. */
+export async function deleteMessage(page: Page, text: string): Promise<Sent> {
+  const menu = await openMessageMenu(page, text);
+  return capture(
+    page,
+    (request) => request.method() === 'DELETE' || /delete/i.test(request.url()),
+    () =>
+      clickAndConfirm(
+        page,
+        menu.getByRole('menuitem', { name: 'Delete', exact: true }),
+        /^delete/i,
+      ),
+  );
+}
+
+// ---- Reactions (section 3) ----
+
+const thumbsUp = '(?:👍|thumbs up)';
+
+/** The 👍 chip under a message: the emoji and how many reacted, for example "👍 2". */
+export function thumbsUpChip(page: Page, text: string): Locator {
+  const name = new RegExp(`^(?=.*${thumbsUp})(?=.*\\d)`, 'i');
+  return messageRow(page, text).getByRole('button', { name });
+}
+
+/** How many reacted, from the chip's name; 0 without a chip. */
+export async function reactionCount(chip: Locator): Promise<number> {
+  if ((await chip.count()) === 0) return 0;
+  const name = /^- button "(.*)"/m.exec(await chip.first().ariaSnapshot())?.[1] ?? '';
+  return Number(/\b\d+\b/.exec(name)?.[0] ?? 0);
+}
+
+/** Whether a chip shows the person's own reaction: pressed, or "you" in its name. */
+export async function isOwnReaction(chip: Locator): Promise<boolean> {
+  const snapshot = await chip.first().ariaSnapshot();
+  return /\[pressed\]/.test(snapshot) || /^- button ".*\byou\b.*"/im.test(snapshot);
+}
+
+/**
+ * 👍 from the quick reactions shown when pointing at a message, or from Add reaction in its menu.
+ * Returns the request sent.
+ */
+export async function reactThumbsUp(page: Page, text: string): Promise<Sent> {
+  const row = messageRow(page, text);
+  await row.hover();
+  // A quick reaction has no count in its name; a chip has one.
+  const quick = row.getByRole('button', { name: new RegExp(`^(?!.*\\d)(?=.*${thumbsUp})`, 'i') });
+  const pointed = await quick
+    .first()
+    .waitFor({ timeout: 2_000 })
+    .then(
+      () => true,
+      () => false,
+    );
+  const isReaction = (request: Request) =>
+    /react/i.test(request.url()) || /react|👍/i.test(request.postData() ?? '');
+  return capture(page, isReaction, async () => {
+    if (pointed) return quick.first().click();
+    const menu = await openMessageMenu(page, text);
+    await menu.getByRole('menuitem', { name: /^add reaction/i }).click();
+    const picker = page.getByRole('dialog').last();
+    const emoji = { name: new RegExp(thumbsUp, 'i') };
+    await picker
+      .getByRole('button', emoji)
+      .or(picker.getByRole('option', emoji))
+      .or(picker.getByRole('gridcell', emoji))
+      .first()
+      .click();
+  });
+}
+
+/** Who reacted, from the tooltip shown when pointing at a chip ("Avery Lin and Eli Brooks"). */
+export async function whoReacted(page: Page, chip: Locator): Promise<string> {
+  await chip.first().hover();
+  const tooltip = page.getByRole('tooltip').last();
+  await expect(tooltip).toBeVisible();
+  return tooltip.innerText();
+}
+
+// ---- Message search (section 2, Search results, and section 3) ----
+
+/** The search box at the top of the chat list. */
+export function searchBox(page: Page): Locator {
+  const main = page.getByRole('main');
+  return main
+    .getByRole('searchbox')
+    .or(main.getByRole('textbox', { name: /^search/i }))
+    .first();
+}
+
+/** A message in the search results, by its text (matching words may be marked inside it). */
+export function messageResult(page: Page, text: string): Locator {
+  const main = page.getByRole('main');
+  return main
+    .getByRole('option')
+    .or(main.getByRole('link'))
+    .or(main.getByRole('button'))
+    .filter({ hasText: text })
+    .first();
+}
+
+/** "No messages match." with Clear filters (section 2, States). */
+export const noMatches = (page: Page) => page.getByRole('main').getByText('No messages match.');
+
+/** The From filter: picks one person. */
+export async function filterFrom(page: Page, who: PersonKey): Promise<void> {
+  await page
+    .getByRole('main')
+    .getByRole('button', { name: /^from\b/i })
+    .first()
+    .click();
+  const name = { name: word(firstName[who]) };
+  const person = page
+    .getByRole('option', name)
+    .or(page.getByRole('menuitemradio', name))
+    .or(page.getByRole('menuitemcheckbox', name))
+    .or(page.getByRole('menuitem', name))
+    .first();
+  // A long list of people may need the name typed first.
+  if (
+    !(await person.waitFor({ timeout: 2_000 }).then(
+      () => true,
+      () => false,
+    ))
+  ) {
+    await page.keyboard.type(firstName[who]);
+  }
+  await person.click();
+}
